<template>
  <section class="container py-4 builder">
    <header><div><p class="eyebrow">{{ auth.user?.church?.name }}</p><h1>{{ tr('Formulario de visitas','Visitor form') }}</h1><p>{{ tr('Configura las preguntas que verán los visitantes en el quiosco y al escanear el QR.','Configure questions visitors see at the kiosk and after scanning the QR.') }}</p></div><div class="builder-header-actions"><a v-if="auth.user?.church_id" :href="`/visit/${auth.user.church_id}`" target="_blank" rel="noopener noreferrer" class="btn btn-outline-primary">{{ tr('Ver formulario público ↗','View public form ↗') }}</a><RouterLink to="/greeting/contacts" class="btn btn-outline-secondary">{{ tr('Volver a visitas','Back to visitors') }}</RouterLink><small>{{ tr('Abre la versión publicada en otra pestaña. Publica tus cambios para verlos aquí.','Opens the published version in another tab. Publish your changes to see them here.') }}</small></div></header>
    <p v-if="loading">{{ tr('Cargando…','Loading…') }}</p><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p>
    <template v-if="!loading && loaded">
      <section v-write="'visitors.configure'" class="surface logo-settings"><h2>{{ tr('Logo de la iglesia','Church logo') }}</h2><p>{{ tr('Se muestra en el formulario público y el quiosco. Los cambios del logo se guardan inmediatamente.','Shown on the public form and kiosk. Logo changes are saved immediately.') }}</p><div v-if="logoUrl" class="logo-stage" :style="{textAlign:logoAlignment}"><img :src="logoUrl" :alt="auth.user?.church?.name" class="logo-preview" @load="measureLogo" /></div><p v-if="logoUrl && logoSize" role="status">{{ tr('Imagen original','Original image') }}: {{ logoSize.width }} × {{ logoSize.height }} px · {{ tr('Tamaño de presentación','Display size') }}: {{ logoSize.fittedWidth }} × {{ logoSize.fittedHeight }} px.<br />{{ logoSize.scaled ? tr('Se reducirá proporcionalmente, sin recortes ni deformación.','It will be scaled down proportionally, without cropping or distortion.') : tr('Se puede usar tal cual, sin recortes ni ampliación.','It can be used as is, without cropping or enlargement.') }} {{ tr('En pantallas pequeñas se ajustará al espacio disponible.','On small screens it will fit the available space.') }}</p><label>{{ tr('Alineación del logo','Logo alignment') }}<select class="form-select" :value="logoAlignment" :disabled="logoBusy" @change="alignLogo"><option value="left">{{ tr('Izquierda','Left') }}</option><option value="center">{{ tr('Centro','Center') }}</option><option value="right">{{ tr('Derecha','Right') }}</option></select></label><label>{{ tr('Subir o reemplazar logo','Upload or replace logo') }}<input type="file" accept="image/png,image/jpeg,image/webp" class="form-control" :disabled="logoBusy" @change="uploadLogo" /></label><p class="muted">PNG, JPG, WebP · {{ tr('Máximo 2 MB y 4096 × 4096 píxeles.','Maximum 2 MB and 4096 × 4096 pixels.') }}</p><button v-if="logoUrl" class="btn btn-outline-primary me-2" :disabled="logoBusy" @click="prepareTransparentLogo">{{ tr('Quitar fondo blanco','Remove white background') }}</button><div v-if="transparentPreview" class="background-preview"><h3>{{ tr('Revisa antes de aplicar','Review before applying') }}</h3><p>{{ tr('Solo se quita el blanco conectado a los bordes. Revisa los detalles blancos que toquen el borde; también pueden desaparecer. El logo actual no cambia hasta que apliques el resultado.','Only white connected to the edges is removed. Check white details touching an edge; they may also disappear. Your current logo stays unchanged until you apply the result.') }}</p><div class="comparison"><figure><figcaption>{{ tr('Original','Original') }}</figcaption><div class="transparency-grid"><img :src="logoUrl" alt="Original" /></div></figure><figure><figcaption>{{ tr('Sin fondo blanco','Without white background') }}</figcaption><div class="transparency-grid"><img :src="transparentPreview" :alt="tr('Vista previa sin fondo','Background removal preview')" /></div></figure></div><button class="btn btn-primary me-2" :disabled="logoBusy" @click="applyTransparentLogo">{{ tr('Aplicar resultado','Apply result') }}</button><button class="btn btn-outline-secondary" :disabled="logoBusy" @click="clearTransparentPreview">{{ tr('Conservar original','Keep original') }}</button></div><button v-if="logoUrl" class="btn btn-outline-secondary" :disabled="logoBusy" @click="removeLogo">{{ tr('Quitar logo','Remove logo') }}</button><p v-if="logoBusy" role="status">{{ tr('Guardando…','Saving…') }}</p></section>
      <section v-write="'visitors.configure'" class="getting-started surface">
        <div class="section-heading"><div><h2>{{ tr('Empieza aquí','Start here') }}</h2><p>{{ tr('Elige un punto de partida o aprende a crear tu formulario paso a paso.','Choose a starting point or learn how to build your form step by step.') }}</p></div><button class="btn btn-outline-primary" @click="tutorialOpen ? stopTutorial() : startTutorial()">{{ tutorialOpen?tr('Cerrar guía','Close guide'):tr('¿Cómo funciona?','How does it work?') }}</button></div>
        <div class="template-grid"><button v-for="template in templates" :key="template.id" class="template-option" :disabled="busy" @click="pendingTemplate=template"><strong>{{ template.title }}</strong><span>{{ template.description }}</span></button></div>
        <div v-if="pendingTemplate" class="template-confirm" role="alert">
          <p>{{ tr('Esto reemplazará las preguntas adicionales del borrador. Los campos estándar y las respuestas guardadas se conservan. El formulario público solo cambiará al publicar.','This replaces the draft’s additional questions. Standard fields and saved responses are retained. The public form changes only when you publish.') }}</p>
          <div class="actions"><button class="btn btn-primary" @click="applyTemplate">{{ tr('Usar','Use') }} {{ pendingTemplate.title }}</button><button class="btn btn-outline-secondary" @click="pendingTemplate=null">{{ tr('Cancelar','Cancel') }}</button></div>
        </div>
      </section>
      <div class="builder-note">{{ tr('Nombre, teléfono, correo, dirección, pertenencia a la iglesia y permisos de contacto se conservan como campos estándar. Las respuestas ya enviadas no se modifican.','Name, phone, email, address, church membership and contact permissions remain standard fields. Submitted responses are never modified.') }}</div>
      <div class="builder-grid"><section v-write="'visitors.configure'" class="surface"><div class="section-heading"><h2>{{ tr('Campos adicionales','Additional fields') }}</h2><span>{{ tr('Versión publicada','Published version') }} {{ version }}</span></div>
        <p v-if="!fields.length">{{ tr('Agrega tu primera pregunta o un texto informativo.','Add your first question or informational text.') }}</p>
        <article v-for="(field,index) in fields" :key="field.id" class="field-editor">
          <div class="section-heading"><strong>{{ index+1 }}. {{ typeLabel(field.type) }}</strong><div class="actions"><button type="button" :disabled="busy || index===0" :aria-label="tr('Subir campo','Move field up')" @click="move(index,-1)">↑</button><button type="button" :disabled="busy || index===fields.length-1" :aria-label="tr('Bajar campo','Move field down')" @click="move(index,1)">↓</button><button type="button" :disabled="busy" @click="fields.splice(index,1)">{{ tr('Quitar','Remove') }}</button></div></div>
          <label :class="{'tour-target':tutorialOpen && tutorialStep===2 && field.id===tourFieldId}">{{ field.type==='label'?tr('Texto informativo','Informational text'):tr('Etiqueta de la pregunta','Question label') }}<textarea v-model="field.label" class="form-control" @blur="finishTourLabel(field)" :disabled="busy" maxlength="500" rows="2"></textarea></label>
          <label v-if="field.type==='select'">{{ tr('Opciones (una por línea)','Options (one per line)') }}<textarea :value="field.options.join('\n')" class="form-control" :disabled="busy" rows="3" @input="field.options=$event.target.value.split('\n')"></textarea></label>
          <label v-if="field.type!=='label'" class="check-label"><input v-model="field.required" type="checkbox" :disabled="busy" />{{ field.type==='checkbox'?tr('Debe marcarse para enviar','Must be checked to submit'):tr('Obligatorio','Required') }}</label>
        </article>
        <section class="add-field-panel" aria-labelledby="add-field-title"><div class="add-field-heading"><span class="add-field-icon" aria-hidden="true">＋</span><div><h3 id="add-field-title">{{ tr('Agregar una nueva pregunta','Add a new question') }}</h3><p>{{ tr('Elige el tipo de respuesta y pulsa Agregar campo. La nueva pregunta aparecerá al final de la lista de arriba.','Choose the answer type and select Add field. Your new question will appear at the end of the list above.') }}</p></div></div><div class="add-field"><label :class="{'tour-target':tutorialOpen && tutorialStep===0}">{{ tr('Tipo de campo','Field type') }}<select v-model="newType" class="form-select" @change="advanceTour(0)" :disabled="busy"><option v-for="type in types" :key="type" :value="type">{{ typeLabel(type) }}</option></select></label><button class="btn btn-outline-primary" :class="{'tour-target':tutorialOpen && tutorialStep===1}" :disabled="busy || fields.length>=40" @click="add">+ {{ tr('Agregar campo','Add field') }}</button></div></section>
        <p class="muted">{{ tr('Quitar un campo lo oculta del nuevo formulario; sus respuestas anteriores se conservan.','Removing a field hides it from the new form; previous answers are retained.') }}</p>
        <button class="btn btn-primary" :class="{'tour-target':tutorialOpen && tutorialStep===4}" :disabled="busy" @click="publish">{{ busy?tr('Publicando…','Publishing…'):tr('Publicar formulario','Publish form') }}</button><button class="btn btn-outline-secondary ms-2" :disabled="busy" @click="load">{{ tr('Descartar cambios','Discard changes') }}</button>
      </section><section class="surface preview" :class="{'tour-target':tutorialOpen && tutorialStep===3}" @input="advanceTour(3)" @change="advanceTour(3)"><h2>{{ tr('Vista previa de preguntas adicionales','Additional questions preview') }}</h2><p class="muted">{{ tr('Se mostrarán después de los datos estándar de contacto.','These appear after the standard contact details.') }}</p><VisitorCustomFields :fields="fields" v-model="preview" /></section></div>
    </template>
    <template v-if="tutorialOpen">
      <div class="tour-shade" aria-hidden="true"></div>
      <aside class="tour-coach" role="region" aria-label="Tutorial" aria-live="polite">
        <div class="section-heading"><strong>{{ tr('Paso','Step') }} {{ tutorialStep+1 }} / 5</strong><button class="btn btn-outline-secondary" @click="stopTutorial">{{ tr('Salir de la guía','Exit guide') }}</button></div>
        <h2>{{ tutorialSteps[tutorialStep].title }}</h2><p>{{ tutorialSteps[tutorialStep].text }}</p>
        <p class="tour-hint">{{ tr('Completa la acción resaltada para continuar. Puedes salir en cualquier momento; los cambios quedan como borrador.','Complete the highlighted action to continue. You can exit at any time; changes remain a draft.') }}</p>
      </aside>
    </template>
  </section>
</template>
<script setup>
import {ref,onMounted,onUnmounted,computed,nextTick,watch} from 'vue'
import {removeEdgeWhite} from '../utils/removeWhiteBackground'
import VisitorCustomFields from './VisitorCustomFields.vue'
import {churchContactsApi} from '../services/churchContactsApi'
import {useAuthStore} from '../stores/authStore'
import {useUiStore} from '../stores/uiStore'
const auth=useAuthStore(),ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const types=['text','textarea','number','date','select','checkbox','label']
const typeLabel=t=>({text:tr('Texto corto','Short text'),textarea:tr('Texto largo','Long text'),number:tr('Número','Number'),date:tr('Fecha','Date'),select:tr('Lista de opciones','Dropdown'),checkbox:tr('Casilla','Checkbox'),label:tr('Etiqueta / información','Label / information')})[t]
const tutorialOpen=ref(false),tutorialStep=ref(0),pendingTemplate=ref(null)
const tourFieldId=ref(null)
const tutorialSteps=computed(()=>[
  {title:tr('Elige Texto corto','Choose Short text'),text:tr('En Tipo de campo, selecciona Texto corto para crear una pregunta de respuesta libre.','Under Field type, select Short text to create an open-answer question.')},
  {title:tr('Agrega la pregunta','Add the question'),text:tr('Pulsa Agregar campo. Se agregará una pregunta al final de tu borrador.','Select Add field. A question will be added at the end of your draft.')},
  {title:tr('Escribe la pregunta','Write the question'),text:tr('Escribe una etiqueta, por ejemplo: ¿Cómo conociste nuestra iglesia? Luego sal del campo para continuar.','Write a label, for example: How did you hear about our church? Then leave the field to continue.')},
  {title:tr('Prueba tu formulario','Try your form'),text:tr('Escribe una respuesta de prueba en Vista previa. Esta respuesta no se guarda.','Type a sample answer in Preview. This response is not saved.')},
  {title:tr('Publica cuando esté listo','Publish when ready'),text:tr('Publicar hará disponible todo el borrador en el quiosco y QR. Si solo estás practicando, sal de la guía y usa Descartar cambios.','Publishing makes the entire draft available at the kiosk and QR. If you are only practicing, exit the guide and use Discard changes.')}
])
async function focusTour(){await nextTick();document.querySelector('.tour-target')?.scrollIntoView({behavior:'smooth',block:'center'})}
function startTutorial(){if(fields.value.length>=40){error.value=tr('Quita un campo para hacer espacio antes de iniciar la guía.','Remove a field to make room before starting the guide.');return}tutorialStep.value=0;newType.value='';tutorialOpen.value=true;focusTour()}
function stopTutorial(){tutorialOpen.value=false;if(!newType.value)newType.value='text'}
function advanceTour(step){if(tutorialOpen.value && tutorialStep.value===step){if(step===0 && newType.value!=='text')return;tutorialStep.value++}}
function finishTourLabel(field){if(field.id===tourFieldId.value && field.label.trim())advanceTour(2)}
watch(tutorialStep,focusTour)
const templates=computed(()=>[
  {id:'blank',title:tr('Lienzo en blanco','Blank canvas'),description:tr('Solo datos estándar; agrega tus propias preguntas.','Standard details only; add your own questions.'),fields:[]},
  {id:'welcome',title:tr('Primera visita','First visit'),description:tr('Conoce cómo llegaron y qué les interesa.','Learn how visitors found you and what interests them.'),fields:[
    {type:'select',label:tr('¿Cómo conociste nuestra iglesia?','How did you hear about our church?'),options:[tr('Amigos o familia','Friends or family'),tr('Internet','Internet'),tr('Pasaba por aquí','Passing by'),tr('Otro','Other')]},
    {type:'textarea',label:tr('¿Qué te gustaría conocer de nuestra iglesia?','What would you like to learn about our church?')}]},
  {id:'pastoral',title:tr('Acompañamiento pastoral','Pastoral care'),description:tr('Ofrece un espacio para solicitar oración o una conversación.','Offer space to request prayer or a conversation.'),fields:[
    {type:'label',label:tr('Comparte solo lo que desees. Estas preguntas son opcionales.','Share only what you wish. These questions are optional.')},
    {type:'textarea',label:tr('¿Tienes alguna petición de oración?','Do you have a prayer request?')},
    {type:'checkbox',label:tr('Me gustaría conversar con el pastor','I would like to speak with the pastor')}]}
])
function applyTemplate(){fields.value=pendingTemplate.value.fields.map(f=>({id:crypto.randomUUID(),required:false,options:[],...f}));preview.value={};pendingTemplate.value=null;notice.value=tr('Plantilla cargada como borrador. Revisa y publica cuando esté lista.','Template loaded as a draft. Review and publish when ready.')}
const logoUrl=ref(null),logoBusy=ref(false),logoAlignment=ref('center'),logoSize=ref(null)
const transparentPreview=ref(null)
let transparentBlob=null
function clearTransparentPreview(){if(transparentPreview.value)URL.revokeObjectURL(transparentPreview.value);transparentPreview.value=null;transparentBlob=null}
onUnmounted(clearTransparentPreview)
async function prepareTransparentLogo(){
  logoBusy.value=true;error.value='';notice.value='';clearTransparentPreview()
  let bitmap
  try{
    const response=await fetch(logoUrl.value)
    if(!response.ok)throw new Error('load')
    bitmap=await createImageBitmap(await response.blob())
    if(bitmap.width>4096 || bitmap.height>4096)throw new Error('size')
    const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height
    const context=canvas.getContext('2d');context.drawImage(bitmap,0,0)
    const image=context.getImageData(0,0,canvas.width,canvas.height)
    const removed=removeEdgeWhite(image.data,canvas.width,canvas.height)
    if(!removed){notice.value=tr('No se encontró fondo blanco conectado a los bordes. Se conserva el original.','No white background connected to the edges was found. The original is retained.');return}
    if(!image.data.some((value,index)=>index%4===3 && value>0)){error.value=tr('El resultado quedaría vacío. Se conserva el original.','The result would be empty. The original is retained.');return}
    context.putImageData(image,0,0)
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'))
    if(!blob || blob.size>2*1024*1024){error.value=tr('El PNG resultante supera el límite de 2 MB. Usa una imagen más pequeña.','The resulting PNG exceeds the 2 MB limit. Use a smaller image.');return}
    transparentBlob=blob;transparentPreview.value=URL.createObjectURL(blob)
  }catch{error.value=tr('No se pudo procesar el logo. Se conserva el original.','Unable to process the logo. The original is retained.')}
  finally{bitmap?.close();logoBusy.value=false}
}
async function applyTransparentLogo(){if(!transparentBlob)return;logoBusy.value=true;error.value='';try{const result=await churchContactsApi.uploadLogo(new File([transparentBlob],'church-logo.png',{type:'image/png'}));logoUrl.value=result.logo_url;clearTransparentPreview();notice.value=tr('Logo sin fondo guardado.','Logo without background saved.')}catch(e){error.value=message(e)}finally{logoBusy.value=false}}
function measureLogo(event){const {naturalWidth:width,naturalHeight:height}=event.target;const ratio=Math.min(1,220/width,110/height);logoSize.value={width,height,fittedWidth:Math.round(width*ratio),fittedHeight:Math.round(height*ratio),scaled:ratio<1}}
async function alignLogo(event){logoBusy.value=true;error.value='';try{const result=await churchContactsApi.alignLogo(event.target.value);logoAlignment.value=result.logo_alignment}catch(e){error.value=message(e);event.target.value=logoAlignment.value}finally{logoBusy.value=false}}
async function uploadLogo(event){const file=event.target.files?.[0];if(!file)return;logoBusy.value=true;error.value='';notice.value='';try{const result=await churchContactsApi.uploadLogo(file);logoUrl.value=result.logo_url;clearTransparentPreview();notice.value=tr('Logo actualizado.','Logo updated.')}catch(e){error.value=message(e)}finally{logoBusy.value=false;event.target.value=''}}
async function removeLogo(){logoBusy.value=true;error.value='';notice.value='';try{await churchContactsApi.removeLogo();logoUrl.value=null;clearTransparentPreview();notice.value=tr('Logo eliminado.','Logo removed.')}catch(e){error.value=message(e)}finally{logoBusy.value=false}}
const fields=ref([]),version=ref(0),newType=ref('text'),preview=ref({}),loading=ref(true),loaded=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const message=e=>Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||tr('No se pudo guardar.','Could not save.')
async function load(){loading.value=true;error.value='';notice.value='';try{const form=await churchContactsApi.form();fields.value=form.fields;logoUrl.value=form.logo_url;logoAlignment.value=form.logo_alignment || 'center';version.value=form.version;preview.value={};pendingTemplate.value=null;loaded.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
function add(){const id=crypto.randomUUID();fields.value.push({id,type:newType.value,label:'',required:false,options:[]});if(tutorialOpen.value && tutorialStep.value===1){tourFieldId.value=id;advanceTour(1)}}
function move(i,d){const field=fields.value.splice(i,1)[0];fields.value.splice(i+d,0,field)}
async function publish(){busy.value=true;error.value='';notice.value='';try{const form=await churchContactsApi.publishForm({base_version:version.value,fields:fields.value.map(f=>({...f,label:f.label.trim(),options:f.options.map(o=>o.trim()).filter(Boolean)}))});version.value=form.version;fields.value=form.fields;stopTutorial();notice.value=tr('Formulario publicado. Ya está disponible en el quiosco y QR.','Form published. It is now available at the kiosk and QR link.')}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(load)
</script>
<style scoped>
.builder{font-size:13px;min-width:0}.builder header,.section-heading,.actions,.add-field{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}.builder header{margin-bottom:20px}.builder h1{font-size:22px}.builder h2{font-size:16px}.builder p,.muted{color:#627267}.eyebrow{color:#26705c!important}.builder-note{padding:16px;background:#eef5f0;border-radius:8px;margin-bottom:18px}.builder-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:18px}.surface{min-width:0;background:white;border:1px solid #dce5df;border-radius:10px;padding:20px}.field-editor{border:1px solid #dce5df;border-radius:8px;padding:14px;margin:14px 0;display:grid;gap:12px}.field-editor label{display:block}.field-editor .check-label{display:flex;gap:8px;align-items:center}.check-label input{width:16px;height:16px}.builder .form-control,.builder .form-select{font-size:13px;margin-top:5px}.builder button{width:auto;font-size:12px}.actions button{border:1px solid #dce5df;border-radius:5px;background:#f8faf9;padding:5px 9px}.add-field{margin:16px 0}.add-field label{flex:1}.preview{align-self:start}.btn-primary{background:#1f6f5c;border-color:#1f6f5c}@media(max-width:850px){.builder-grid{grid-template-columns:1fr}.surface{padding:14px}}
/* Explicit foreground/background pairs keep global button styles from leaking in. */
.builder{color:#243d32}
.builder .builder-note{color:#344f41}
.builder .actions button{color:#344f41;background:#f8faf9;border-color:#9aaea1}
.builder .actions button:hover:not(:disabled){color:#173e2d;background:#e4eee7;border-color:#527761}
.builder .actions button:disabled{color:#647269;background:#edf1ee;border-color:#c5d0c9;cursor:not-allowed;opacity:1}
.builder .btn-outline-primary{color:#1f6f5c;background:#fff;border-color:#1f6f5c}
.builder .btn-outline-primary:hover:not(:disabled){color:#fff;background:#1f6f5c}
.builder .btn-outline-secondary{color:#4f6056;background:#fff;border-color:#76867c}
.builder .btn-outline-secondary:hover:not(:disabled){color:#fff;background:#4f6056}
.builder .btn-primary{color:#fff;background:#1f6f5c;border-color:#1f6f5c}
.builder .btn-primary:hover:not(:disabled){color:#fff;background:#185544;border-color:#185544}
.builder button:focus-visible,.builder a:focus-visible{outline:3px solid #25785e;outline-offset:3px;box-shadow:none}
.builder .form-control,.builder .form-select{color:#243d32;background-color:#fff}
.builder .form-control:disabled,.builder .form-select:disabled{color:#52645a;background-color:#edf1ee}
.getting-started{margin-bottom:18px}.getting-started h2{margin-bottom:6px}.template-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}.builder .template-option{text-align:left;background:#f8faf9;color:#243d32;border:1px solid #9aaea1;padding:16px;display:grid;gap:8px;width:100%}.builder .template-option:hover:not(:disabled){background:#e4eee7;border-color:#1f6f5c}.template-option span{color:#52645a;font-size:13px}.tutorial,.template-confirm{padding:16px;margin-top:16px;border:1px solid #9aaea1;border-radius:8px;background:#f2f6f3}.tutorial h3{font-size:16px}.tutorial .actions,.template-confirm .actions{justify-content:flex-start}.builder .btn:disabled{opacity:1;color:#647269;background:#edf1ee;border-color:#c5d0c9}@media(max-width:650px){.template-grid{grid-template-columns:1fr}}
.tour-shade{position:fixed;inset:0;background:rgba(12,28,21,.65);z-index:2000}.builder .tour-target{position:relative;z-index:2001;background:#fff;border-radius:8px;outline:4px solid #7ed9b4;outline-offset:5px;scroll-margin-bottom:260px}.builder .tour-target.btn-primary{background:#1f6f5c}.tour-coach{position:fixed;right:20px;bottom:20px;width:min(420px,calc(100vw - 32px));z-index:2002;padding:20px;background:#fff;color:#243d32;border:1px solid #9aaea1;border-radius:12px;box-shadow:0 8px 40px #0004}.tour-coach h2{margin-top:12px}.tour-coach p{margin-bottom:8px}.tour-hint{font-size:12px}.tour-coach .section-heading{gap:8px}@media(max-width:650px){.tour-coach{right:16px;bottom:12px;padding:14px}.builder .tour-target{scroll-margin-bottom:320px}}
